"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  MapPin,
  CreditCard,
  Tag,
  ChevronRight,
  Check,
  Plus,
  Truck,
} from "lucide-react";
import Link from "next/link";
import { bagItems } from "@/data/bagItems";
import CheckoutStages from "../../_components/CheckoutProgress";

export default function ReviewPage() {
  const [coupon, setCoupon] = useState("");
  const [isApplied, setIsApplied] = useState(false);

  // Mock data for the UI
  const address = {
    name: "Alex Rivera",
    street: "2244 Luxury Lane, Suite 400",
    city: "New York, NY 10013",
    phone: "+1 (555) 000-9999",
  };

  return (
    <div className="min-h-screen bg-background text-foreground transition-colors duration-300 px-4 md:px-6 lg:py-20">
      {/* 1. Progress Indicator (Stage 2: Review/Shipping) */}
      <CheckoutStages currentStage={2} />

      <main className="mx-auto max-w-8xl">
        <div className="flex flex-col lg:flex-row gap-16 lg:items-start">
          {/* LEFT COLUMN: Logistics & Details */}
          <div className="flex-1 space-y-12">
            {/* Shipping Address Section */}
            <section>
              <div className="flex items-center justify-between mb-8">
                <h2 className="text-2xl font-black uppercase tracking-tighter">
                  Shipping Details
                </h2>
                <button className="text-xs font-bold uppercase tracking-widest text-foreground-subtle hover:text-foreground underline underline-offset-4 transition-colors">
                  Change
                </button>
              </div>

              <motion.div
                whileHover={{ y: -4 }}
                className="relative p-8 rounded-4xl border border-border bg-background-muted/30 group cursor-pointer"
              >
                <div className="flex gap-6">
                  <div className="w-14 h-14 rounded-2xl bg-foreground flex items-center justify-center text-background flex-shrink-0">
                    <MapPin size={24} />
                  </div>
                  <div className="space-y-1">
                    <p className="font-bold text-lg">{address.name}</p>
                    <p className="text-foreground-muted leading-relaxed">
                      {address.street}
                    </p>
                    <p className="text-foreground-muted">{address.city}</p>
                    <p className="pt-2 text-sm font-medium">{address.phone}</p>
                  </div>
                </div>
                <div className="absolute top-8 right-8 w-6 h-6 rounded-full border-2 border-foreground flex items-center justify-center">
                  <div className="w-3 h-3 rounded-full bg-foreground" />
                </div>
              </motion.div>
            </section>

            {/* Delivery Method */}
            <section>
              <h2 className="text-2xl font-black uppercase tracking-tighter mb-8">
                Delivery Method
              </h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="p-6 rounded-3xl border-2 border-foreground bg-background flex justify-between items-center">
                  <div className="flex items-center gap-4">
                    <Truck size={20} />
                    <div>
                      <p className="font-bold text-sm uppercase">
                        Express Delivery
                      </p>
                      <p className="text-xs text-foreground-muted font-medium">
                        2-3 Business Days
                      </p>
                    </div>
                  </div>
                  <span className="font-black text-sm">$15.00</span>
                </div>

                <div className="p-6 rounded-3xl border border-border bg-background-muted/20 flex justify-between items-center opacity-60 hover:opacity-100 transition-opacity cursor-pointer">
                  <div className="flex items-center gap-4">
                    <div className="w-5 h-5 rounded-full border border-border" />
                    <div>
                      <p className="font-bold text-sm uppercase">Standard</p>
                      <p className="text-xs text-foreground-muted font-medium">
                        5-7 Business Days
                      </p>
                    </div>
                  </div>
                  <span className="font-black text-sm">FREE</span>
                </div>
              </div>
            </section>

            {/* Payment Preview */}
            <section>
              <h2 className="text-2xl font-black uppercase tracking-tighter mb-8">
                Payment
              </h2>
              <div className="p-8 rounded-4xl border border-border flex items-center justify-between">
                <div className="flex items-center gap-6">
                  <div className="w-12 h-8 bg-foreground rounded-md flex items-center justify-center">
                    <div className="flex gap-1">
                      <div className="w-3 h-3 rounded-full bg-orange-500" />
                      <div className="w-3 h-3 rounded-full bg-red-500 -ml-2 opacity-80" />
                    </div>
                  </div>
                  <div>
                    <p className="font-bold uppercase tracking-tight">
                      Mastercard •••• 8812
                    </p>
                    <p className="text-xs text-foreground-muted font-medium uppercase tracking-widest">
                      Expires 12/26
                    </p>
                  </div>
                </div>
                <button className="p-2 hover:bg-background-muted rounded-full transition-colors">
                  <ChevronRight size={20} />
                </button>
              </div>
            </section>
          </div>

          {/* RIGHT COLUMN: Order Finalization */}
          <aside className="w-full lg:w-[400px] lg:sticky lg:top-24 space-y-6">
            <div className="p-8 rounded-4xl bg-foreground text-background">
              <h3 className="text-xs font-black uppercase tracking-[0.2em] mb-8 opacity-60">
                Order Summary
              </h3>

              {/* Promo Code Input */}
              <div className="relative mb-8">
                <input
                  type="text"
                  placeholder="PROMO CODE"
                  className="w-full bg-background/10 border border-background/20 rounded-full py-4 px-6 text-xs font-bold uppercase tracking-widest focus:outline-none focus:border-background/50 transition-all placeholder:text-background/40"
                  value={coupon}
                  onChange={(e) => setCoupon(e.target.value)}
                />
                <button
                  onClick={() => setIsApplied(!isApplied)}
                  className="absolute right-2 top-2 bottom-2 px-6 rounded-full bg-background text-foreground text-[10px] font-black uppercase tracking-widest active:scale-95 transition-transform"
                >
                  {isApplied ? <Check size={14} /> : "Apply"}
                </button>
              </div>

              {/* Pricing Breakdown */}
              <div className="space-y-4 mb-8">
                <div className="flex justify-between text-sm">
                  <span className="opacity-60 uppercase font-bold tracking-tighter">
                    Subtotal
                  </span>
                  <span className="font-black">$3,798.00</span>
                </div>
                <div className="flex justify-between text-sm text-emerald-400">
                  <span className="uppercase font-bold tracking-tighter">
                    Discount
                  </span>
                  <span className="font-black">-$120.00</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="opacity-60 uppercase font-bold tracking-tighter">
                    Shipping
                  </span>
                  <span className="font-black">$15.00</span>
                </div>
                <div className="pt-4 border-t border-background/10 flex justify-between items-end">
                  <span className="text-xs font-black uppercase tracking-[0.2em]">
                    Total
                  </span>
                  <span className="text-4xl font-black tracking-tighter leading-none">
                    $3,693.00
                  </span>
                </div>
              </div>

              <Link
                href="/checkout/success"
                className="group relative flex items-center justify-center w-full bg-background text-foreground rounded-full py-6 transition-all hover:pr-8 active:scale-[0.98]"
              >
                <span className="font-black uppercase tracking-[0.2em] text-sm">
                  Place Order
                </span>
                <div className="absolute right-6 opacity-0 group-hover:opacity-100 transition-all transform translate-x-[-10px] group-hover:translate-x-0">
                  <ChevronRight size={20} />
                </div>
              </Link>
            </div>

            {/* Support Note */}
            <div className="p-6 rounded-3xl border border-border text-center">
              <p className="text-[10px] font-bold uppercase tracking-widest text-foreground-subtle">
                Secure SSL Checkout • Free returns within 30 days
              </p>
            </div>
          </aside>
        </div>
      </main>
    </div>
  );
}
